57	func (c *clusterInfoUpdater) Run(ctx context.Context) {
58		c.updateClusters()
59		ticker := time.NewTicker(clusterInfoTimeout)
60		for {
61			select {
62			case <-ctx.Done():
63				ticker.Stop()
64				return
65			case <-ticker.C:
66				c.updateClusters()
67			}
68		}
69	}
